import{_ as a,o as t,c as s,a3 as r}from"./chunks/framework.I6s8z2kk.js";const d=JSON.parse('{"title":"Purchases, balance and payouts","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/purchases-payouts.md","filePath":"user/center/purchases-payouts.md"}'),n={name:"user/center/purchases-payouts.md"};function o(i,e,h,c,l,u){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="purchases-balance-and-payouts" tabindex="-1">Purchases, balance and payouts <a class="header-anchor" href="#purchases-balance-and-payouts" aria-label="Permalink to &quot;Purchases, balance and payouts&quot;">​</a></h1><h2 id="purchases" tabindex="-1">Purchases <a class="header-anchor" href="#purchases" aria-label="Permalink to &quot;Purchases&quot;">​</a></h2><p><strong>Purchases</strong> shows what clients bought from you. Which ones you see depends on your permissions: you need the view permission for each service type, and separate permissions to see other trainers&#39; sales, sales not linked to a trainer, and prices. The owner sees everything. You can export purchases if you have the permission.</p><h2 id="fees" tabindex="-1">Fees <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;Fees&quot;">​</a></h2><p>The platform charges a <strong>fee</strong> on each sale. It is taken from your earnings and does <strong>not</strong> change what the client pays. It is returned if the sale is cancelled or fully refunded.</p><h2 id="balance" tabindex="-1">Balance <a class="header-anchor" href="#balance" aria-label="Permalink to &quot;Balance&quot;">​</a></h2><p><strong>Balance</strong> shows what the platform owes you.</p><ul><li><strong>Online payments</strong> are added after a short hold period.</li><li>Fees, refunds and discounts paid for by the platform adjust the balance.</li><li><strong>Cash and manual payments</strong> you collected yourself are not part of it.</li></ul><h2 id="payouts" tabindex="-1">Payouts <a class="header-anchor" href="#payouts" aria-label="Permalink to &quot;Payouts&quot;">​</a></h2><p>Every week the platform creates a <strong>payout</strong> for your available balance and pays it to your bank account. You can see each payout and its status (<strong>Pending</strong>, <strong>Paid</strong>, <strong>Cancelled</strong>).</p><p>The <strong>owner should set the payout account</strong> (IBAN). A payout is still created without it, but the platform cannot transfer it until you add the account, and payouts already created keep the account they had at the time. A zero or negative balance is also carried over.</p><h2 id="verifying-a-payment" tabindex="-1">Verifying a payment <a class="header-anchor" href="#verifying-a-payment" aria-label="Permalink to &quot;Verifying a payment&quot;">​</a></h2><p>If a client says they paid but the booking is still pending, use <strong>Verify payment</strong> on the purchase. The payment status is checked directly with the payment provider.</p>',13)])])}const y=a(n,[["render",o]]);export{d as __pageData,y as default};
